/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_oneshot.c
 *
 * D13x 定时器驱动（arch_alarm 模型）
 * GTC 寄存器来源: D13x User Manual §11.1 + luban-lite
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/timers/oneshot.h>
#include <nuttx/timers/arch_alarm.h>
#include <nuttx/irq.h>
#include <nuttx/arch.h>
#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* GTC 寄存器偏移 (来源: D13x User Manual §11.1.3 表 11-1) */

#define GTC_CNTCR                (D13X_GTC_BASE + 0x0000)  /* 计数器控制 */
#define GTC_CNTSR                (D13X_GTC_BASE + 0x0004)  /* 计数器状态 */
#define GTC_CNTVL                (D13X_GTC_BASE + 0x0008)  /* 计数值低位 [31:0] */
#define GTC_CNTVH                (D13X_GTC_BASE + 0x000C)  /* 计数值高位 [51:32] */
#define GTC_CNTFID0              (D13X_GTC_BASE + 0x0020)  /* 计数频率 ID0 = 4MHz */
#define GTC_CNTFID1              (D13X_GTC_BASE + 0x0024)  /* 计数频率 ID1 = 1MHz */
#define GTC_CNTFID2              (D13X_GTC_BASE + 0x0028)  /* 计数频率 ID2 = 250KHz */
#define GTC_CONFG                (D13X_GTC_BASE + 0x00C0)  /* 配置: FDIV 分频 */

/* GTC_CNTCR 位定义 */

#define GTC_CNTCR_EN             (1 << 0)   /* 计数器使能 */
#define GTC_CNTCR_HDBG           (1 << 1)   /* 调试时保持 */

/* GTC 中断号: GTC 通过 CLIC 直接产生中断，IRQ 号取决于硬件连线
 * luban-lite 使用 CORET (IRQ 7) 作为系统 tick，GTC 仅用于使能计数
 * NuttX arch_alarm 模型需要一个 IRQ，使用 CORET_IRQn (7) 或
 * 通过 oneshot 软件比较实现。此处使用 CORET_IRQn 作为中断源。
 */

#define D13X_IRQ_GTC             7   /* CORET_IRQn, 与 luban-lite 一致 */

/* GTC 时钟频率: 基频 4MHz (D13x User Manual §11.1.1)
 * PCLK 可选 12/24/48/60 MHz，GTC 内部分频到 4MHz 基频
 * luban-lite system.c 中: *(volatile uint32_t *)GTC_BASE = 0x0001 (使能)
 * 计数频率由 GTC_CONFG 的 FDIV 字段控制
 */

#define GTC_BASE_FREQ            4000000    /* 4MHz 基频 */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct d13x_oneshot_lowerhalf_s
{
  struct oneshot_lowerhalf_s lower;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct d13x_oneshot_lowerhalf_s g_d13x_oneshot;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: d13x_oneshot_current
 *
 * Description:
 *   Get the current timer value (clkcnt_t API)
 *
 ****************************************************************************/

static clkcnt_t d13x_oneshot_current(struct oneshot_lowerhalf_s *lower)
{
  /* 读取 64-bit 计数值: 先读高 32 位，再读低 32 位，再读高 32 位
   * 如果高 32 位变化了，说明发生了进位，需要重读
   */

  uint32_t high1, low, high2;

  do
    {
      high1 = getreg32(GTC_CNTVH);
      low   = getreg32(GTC_CNTVL);
      high2 = getreg32(GTC_CNTVH);
    }
  while (high1 != high2);

  return (clkcnt_t)(((uint64_t)high1 << 32) | low);
}

/****************************************************************************
 * Name: d13x_oneshot_start
 *
 * Description:
 *   Start the oneshot timer with a relative delay (clkcnt_t API)
 *
 ****************************************************************************/

static void d13x_oneshot_start(struct oneshot_lowerhalf_s *lower,
                               clkcnt_t delay)
{
  uint32_t now_lo = getreg32(GTC_CNTVL);
  uint32_t cmp = now_lo + (uint32_t)delay;

  putreg32(cmp, GTC_CNTVL);  /* 写入比较值到低 32 位 */
}

/****************************************************************************
 * Name: d13x_oneshot_start_absolute
 *
 * Description:
 *   Start the oneshot timer with an absolute counter value (clkcnt_t API)
 *
 ****************************************************************************/

static void d13x_oneshot_start_absolute(struct oneshot_lowerhalf_s *lower,
                                        clkcnt_t cnt)
{
  putreg32((uint32_t)cnt, GTC_CNTVL);
}

/****************************************************************************
 * Name: d13x_oneshot_cancel
 *
 * Description:
 *   Cancel the oneshot timer (clkcnt_t API)
 *
 ****************************************************************************/

static void d13x_oneshot_cancel(struct oneshot_lowerhalf_s *lower)
{
  /* 清除比较匹配: 写入一个不会匹配的值 */
  putreg32(0xFFFFFFFF, GTC_CNTVL);
}

/****************************************************************************
 * Name: d13x_oneshot_maxdelay
 *
 * Description:
 *   Get the maximum delay value (clkcnt_t API)
 *
 ****************************************************************************/

static clkcnt_t d13x_oneshot_maxdelay(struct oneshot_lowerhalf_s *lower)
{
  return (clkcnt_t)0xFFFFFFFF;
}

/****************************************************************************
 * Name: d13x_oneshot_handler
 *
 * Description:
 *   Timer interrupt handler (CORET_IRQn)
 *
 ****************************************************************************/

static int d13x_oneshot_handler(int irq, FAR void *context, FAR void *arg)
{
  struct oneshot_lowerhalf_s *lower = arg;

  /* 调用上层回调 */

  if (lower->callback)
    {
      lower->callback(lower, lower->arg);
    }

  return OK;
}

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct oneshot_operations_s g_d13x_oneshot_ops =
{
  .current        = d13x_oneshot_current,
  .start          = d13x_oneshot_start,
  .start_absolute = d13x_oneshot_start_absolute,
  .cancel         = d13x_oneshot_cancel,
  .max_delay      = d13x_oneshot_maxdelay,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: up_timer_initialize
 *
 * Description:
 *   This function is called during start-up to initialize the timer
 *   interrupt.
 *
 ****************************************************************************/

void up_timer_initialize(void)
{
  /* 使能 GTC 计数器 (来源: luban-lite system.c aic_gtc_enable) */

  putreg32(GTC_CNTCR_EN, GTC_CNTCR);

  /* 绑定中断处理函数 (使用 CORET_IRQn, 与 luban-lite 一致) */

  irq_attach(D13X_IRQ_GTC, d13x_oneshot_handler, &g_d13x_oneshot.lower);
  up_enable_irq(D13X_IRQ_GTC);

  /* 初始化 oneshot 计数器，使用 4MHz 基频 */

  oneshot_count_init(&g_d13x_oneshot.lower, GTC_BASE_FREQ);

  /* 创建 oneshot 实例并绑定系统定时器 */

  g_d13x_oneshot.lower.ops = &g_d13x_oneshot_ops;
  up_alarm_set_lowerhalf(&g_d13x_oneshot.lower);
}

/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_irq.c
 *
 * D13x 中断系统适配（CLIC 中断控制器）
 * CLIC 寄存器来源: luban-lite core_rv32.h CLIC_Type 结构体
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/irq.h>
#include <nuttx/arch.h>
#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* CLIC 寄存器结构 (来源: luban-lite core_rv32.h CLIC_Type)
 *
 * CLIC 基地址: 0x20800000
 * 每个中断源占 4 字节: IP(1B), IE(1B), ATTR(1B), CTL(1B)
 * CLICINT[] 数组起始偏移: 0x1000
 *
 * struct CLIC_Type {
 *   uint32_t CLICCFG;      // offset 0x000
 *   uint32_t CLICINFO;     // offset 0x004
 *   uint32_t MINTTHRESH;   // offset 0x008
 *   uint32_t RESERVED[1021];
 *   CLIC_INT_Control CLICINT[4096];  // offset 0x1000
 * };
 *
 * struct CLIC_INT_Control {
 *   uint8_t IP;    // offset +0x000 (pending)
 *   uint8_t IE;    // offset +0x004 (enable)
 *   uint8_t ATTR;  // offset +0x008 (attribute: vector/shv)
 *   uint8_t CTL;   // offset +0x00C (control: priority)
 * };
 */

#define D13X_CLIC_BASE         D13X_E907_CLIC_BASE   /* 0x20800000 */
#define D13X_CLIC_CFG          (D13X_CLIC_BASE + 0x0000)
#define D13X_CLIC_INFO         (D13X_CLIC_BASE + 0x0004)
#define D13X_CLIC_MINTTHRESH   (D13X_CLIC_BASE + 0x0008)
#define D13X_CLIC_INT_BASE     (D13X_CLIC_BASE + 0x1000)  /* CLICINT[] 起始 */

/* 中断向量表地址（RISC-V 使用 __trap_vec） */

extern uint32_t __trap_vec[];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: d13x_clic_set_irq
 *
 * Description:
 *   设置指定中断的 IE/IP/ATTR 寄存器
 *
 ****************************************************************************/

static inline void d13x_clic_enable_irq(int irq)
{
  /* CLICINT[irq].IE = 1 */

  volatile uint8_t *ie = (volatile uint8_t *)(D13X_CLIC_INT_BASE + irq * 4 + 1);
  *ie = 1;
}

static inline void d13x_clic_disable_irq(int irq)
{
  /* CLICINT[irq].IE = 0 */

  volatile uint8_t *ie = (volatile uint8_t *)(D13X_CLIC_INT_BASE + irq * 4 + 1);
  *ie = 0;
}

static inline void d13x_clic_clear_pending(int irq)
{
  /* CLICINT[irq].IP = 0 (W1C) */

  volatile uint8_t *ip = (volatile uint8_t *)(D13X_CLIC_INT_BASE + irq * 4 + 0);
  *ip = 0;
}

static inline void d13x_clic_set_attr(int irq, uint8_t attr)
{
  /* CLICINT[irq].ATTR = attr */

  volatile uint8_t *attrp = (volatile uint8_t *)(D13X_CLIC_INT_BASE + irq * 4 + 2);
  *attrp = attr;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: up_irqinitialize
 *
 * Description:
 *   Initialize the interrupt subsystem
 *
 ****************************************************************************/

void up_irqinitialize(void)
{
  int i;

  /* 配置 mtvec (mode 3) + mtvt 双 CSR */

  uint32_t mtvec = (uint32_t)__trap_vec | 0x3;
  __asm__ __volatile__("csrw mtvec, %0" :: "r"(mtvec));

  /* mtvt CSR (T-Head 扩展，CSR 编号 0x7C0) */

  uint32_t mtvt = (uint32_t)__trap_vec;
  __asm__ __volatile__("csrw 0x7C0, %0" :: "r"(mtvt));

  /* 初始化 CLIC 中断控制器 (来源: luban-lite system.c SystemInit) */

  /* 读取 CLIC 配置信息 */

  volatile uint32_t *cliccfg = (volatile uint32_t *)D13X_CLIC_CFG;
  volatile uint32_t *clicinfo = (volatile uint32_t *)D13X_CLIC_INFO;

  uint32_t info = *clicinfo;
  uint32_t nlbits = (info >> 21) & 0xF;

  *cliccfg = (nlbits << 1) & 0x1E;

  /* 初始化所有中断: 清除 pending, 使能向量中断 */

  for (i = 0; i < 96; i++)
    {
      d13x_clic_clear_pending(i);
      d13x_clic_set_attr(i, 1);  /* use vector interrupt */
    }

  /* 使能全局中断 */

  up_irq_enable();
}

/****************************************************************************
 * Name: up_enable_irq
 *
 * Description:
 *   Enable the interrupt specified by 'irq'
 *
 ****************************************************************************/

void up_enable_irq(int irq)
{
  d13x_clic_enable_irq(irq);
}

/****************************************************************************
 * Name: up_disable_irq
 *
 * Description:
 *   Disable the interrupt specified by 'irq'
 *
 ****************************************************************************/

void up_disable_irq(int irq)
{
  d13x_clic_disable_irq(irq);
}

/****************************************************************************
 * Name: riscv_dispatch_irq
 *
 * Description:
 *   Process interrupt and dispatch to registered handler
 *
 ****************************************************************************/

void *riscv_dispatch_irq(uint32_t mcause, uint32_t *regs)
{
  int irq;

  /* 读取中断号 */

  irq = (int)(mcause & 0x7FFFFFFF);

  /* 调用中断处理函数 */

  irq_dispatch(irq, regs);

  return regs;
}

/****************************************************************************
 * Name: up_irq_enable
 *
 * Description:
 *   Enable all interrupts
 *
 ****************************************************************************/

irqstate_t up_irq_enable(void)
{
  irqstate_t flags;

  /* 读取当前中断状态 */

  __asm__ __volatile__("csrr %0, mstatus" : "=r"(flags));

  /* 使能中断 */

  __asm__ __volatile__("csrsi mstatus, 0x8");

  return flags;
}

/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_start.c
 *
 * D13x 启动入口
 * 地址来源: luban-lite aic_soc.h + D13x User Manual
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <nuttx/init.h>
#include <arch/board/board.h>
#include "chip.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* CMU 寄存器地址 (来源: luban-lite aic_soc.h CMU_BASE=0x18020000) */

#define CMU_PLL_IN          (D13X_CMU_BASE + 0x0A4)
#define CMU_PLL_COM         (D13X_CMU_BASE + 0x0A0)
#define CMU_PLL_INT0_GEN    (D13X_CMU_BASE + 0x000)
#define CMU_PLL_INT0_CFG    (D13X_CMU_BASE + 0x040)
#define CMU_PLL_INT1_GEN    (D13X_CMU_BASE + 0x004)
#define CMU_PLL_INT1_CFG    (D13X_CMU_BASE + 0x044)
#define CMU_CLK_CPU         (D13X_CMU_BASE + 0x200)
#define CMU_CLK_AXI_AHB     (D13X_CMU_BASE + 0x100)
#define CMU_CLK_APB0        (D13X_CMU_BASE + 0x120)
#define CMU_CLK_UART0       (D13X_CMU_BASE + 0x840)
#define CMU_CLK_GPIO        (D13X_CMU_BASE + 0x83C)

/* eFuse 寄存器 (来源: luban-lite aic_soc.h SID_BASE=0x19010000) */

#define EFUSE_CMU_REG       (D13X_CMU_BASE + 0x904)
#define EFUSE_218_REG       (D13X_SID_BASE + 0x218)

/* WDOG 寄存器 (来源: D13x User Manual §11.2, luban-lite aic_soc.h WDT_BASE=0x19000000)
 *
 * WDOG_CTL  = base + 0x000  (Control: enable, debug continue, write protection)
 * WDOG_CNT  = base + 0x004  (Counter value, 32K clock cycles)
 * IRQ_EN    = base + 0x008  (Interrupt enable)
 * IRQ_STA   = base + 0x00C  (Interrupt status, W1C)
 * WDOG_OP   = base + 0x0E8  (Operation command)
 */

#define WDOG_CTL            (D13X_WDT_BASE + 0x000)
#define WDOG_CNT            (D13X_WDT_BASE + 0x004)
#define WDOG_IRQ_EN         (D13X_WDT_BASE + 0x008)
#define WDOG_IRQ_STA        (D13X_WDT_BASE + 0x00C)
#define WDOG_OP             (D13X_WDT_BASE + 0x0E8)

/* WDOG_CTL 位定义 */

#define WDOG_CTL_EN         (1 << 0)   /* 看门狗使能 */
#define WDOG_CTL_DBG_HALT   (1 << 1)   /* 调试时暂停 */
#define WDOG_CTL_W_PROT     (1 << 4)   /* 写保护 */

/* BSS 段符号 */

extern uint32_t _sbss[];
extern uint32_t _ebss[];
extern uint32_t _sdata[];
extern uint32_t _edata[];
extern uint32_t _eronly[];

/* 启动参数位域定义 */

#define get_boot_device(var)      ((var) & 0xF)
#define get_boot_controller(var)  (((var) >> 4) & 0xF)
#define get_boot_reason(var)      (((var) >> 8) & 0xF)
#define get_boot_image_id(var)    (((var) >> 12) & 0xF)

/****************************************************************************
