 ****************************************************************************/

static void d13x_clock_init(void)
{
  uint32_t reg;

  /* 1. 打开 24MHz 振荡器 */

  reg = getreg32(CMU_PLL_IN);
  reg |= (1 << 1);
  putreg32(reg, CMU_PLL_IN);

  /* 2. PLL 公共电路 LDO */

  reg = getreg32(CMU_PLL_COM);
  reg |= (1 << 31);
  reg |= (1 << 0);
  putreg32(reg, CMU_PLL_COM);

  /* 3. 配置 PLL_INT1 → 1.2GHz (N=49) */

  putreg32(0x240C4040, CMU_PLL_INT1_CFG);

  /* 等待 PLL 锁定 */

  while (!(getreg32(CMU_PLL_INT1_CFG) & (1 << 17)));

  /* 4. 配置 PLL_INT0 → 480MHz (N=19) */

  putreg32(0x240C4040, CMU_PLL_INT0_CFG);

  /* 等待 PLL 锁定 */

  while (!(getreg32(CMU_PLL_INT0_CFG) & (1 << 17)));

  /* 5. 总线时钟: AXI/AHB = 200MHz, APB0 = 100MHz */

  putreg32(0x00000001, CMU_CLK_AXI_AHB);
  putreg32(0x00000001, CMU_CLK_APB0);

  /* 6. CPU 时钟: 480MHz */

  putreg32(0x00000100, CMU_CLK_CPU);

  /* 7. 打开 GPIO 时钟 */

  reg = getreg32(CMU_CLK_GPIO);
  reg |= (1 << 12);
  reg |= (1 << 13);
  putreg32(reg, CMU_CLK_GPIO);

  /* 8. 打开 UART0 时钟: 60MHz */

  putreg32(0x00001001, CMU_CLK_UART0);
}

static void d13x_uart_init(void)
{
  uint32_t divisor;

  /* 配置 UART0 引脚复用: PA0→TX, PA1→RX (PIN_FUN=5) */
  /* TODO: 配置 GPIO 引脚复用寄存器 (需要查看 luban-lite pinmux) */

  /* 配置波特率 115200: divisor = 60MHz / (16 × 115200) ≈ 32 */

  divisor = D13X_UART0_FREQ / (16 * D13X_UART0_BAUDRATE);

  /* 禁用 UART */

  putreg32(0, D13X_UART0_BASE + UART_LCR);

  /* 配置波特率 */

  putreg32(divisor & 0xFF, D13X_UART0_BASE + UART_RBR_THR_DLL);
  putreg32((divisor >> 8) & 0xFF, D13X_UART0_BASE + UART_DLH);

  /* 使能 FIFO */

  putreg32(UART_FCR_FIFOE | UART_FCR_RFIFOR | UART_FCR_XFIFOR,
           D13X_UART0_BASE + UART_FCR);

  /* 配置 8N1: 8 数据位, 1 停止位, 无校验 */

  putreg32(0x03, D13X_UART0_BASE + UART_LCR);
}

/****************************************************************************
 * PSRAM 驱动 (D13x)
 * XSPI 基地址: 0x10300000 (来源: luban-lite aic_soc.h)
 ****************************************************************************/

/* XSPI 控制器寄存器 */

#define XSPI_CFG            (D13X_XSPI_BASE + 0x000)
#define XSPI_TIMING         (D13X_XSPI_BASE + 0x004)
#define XSPI_CFG2           (D13X_XSPI_BASE + 0x008)
#define XSPI_CMD            (D13X_XSPI_BASE + 0x100)
#define XSPI_ADDR           (D13X_XSPI_BASE + 0x104)
#define XSPI_DATA           (D13X_XSPI_BASE + 0x108)
#define XSPI_CFG3           (D13X_XSPI_BASE + 0x10C)
#define XSPI_STATUS         (D13X_XSPI_BASE + 0x110)
#define XSPI_CTRL           (D13X_XSPI_BASE + 0x114)
#define XSPI_BCNT           (D13X_XSPI_BASE + 0x118)

/* XSPI 配置位 */

#define XSPI_CFG_EN         (1 << 0)
#define XSPI_CFG_RST        (1 << 1)
#define XSPI_CFG_CLK_EN     (1 << 2)

/* XSPI 状态位 */

#define XSPI_STATUS_BUSY    (1 << 0)
#define XSPI_STATUS_DONE    (1 << 1)

/* PSRAM 命令 */

#define PSRAM_CMD_RESET     0xFF
#define PSRAM_CMD_READ_ID   0x40
#define PSRAM_CMD_WRITE_MR  0xC0
#define PSRAM_CMD_READ_MR   0x40

/* PSRAM 模式寄存器 */

#define PSRAM_MR0           0x00
#define PSRAM_MR4           0x04

static uint32_t d13x_psram_read_efuse(uint32_t reg_addr)
{
  /* 使能 eFuse 时钟 */

  putreg32(0x1100, EFUSE_CMU_REG);

  /* 读取 eFuse 值 */

  uint32_t val = getreg32(reg_addr);

  /* 关闭 eFuse 时钟 */

  putreg32(0x0, EFUSE_CMU_REG);

  return val;
}

static uint32_t d13x_psram_get_size(void)
{
  uint32_t fuse_218 = d13x_psram_read_efuse(EFUSE_218_REG);
  uint8_t mark_id = fuse_218 & 0xFF;

  /* 根据 mark_id 确定 PSRAM 大小 */

  switch (mark_id)
    {
      case 0x00:  /* force use cfg0 */
        return 0;
      case 0x01:  /* D131BAS 4M */
        return 4 * 1024 * 1024;
      case 0x02:  /* D131BBS 8M */
      case 0x03:  /* D131CBS 8M */
      case 0x04:  /* D131EBS/D133EBS 8M */
      case 0x05:  /* D132ENS 8M */
      case 0xA1:  /* DR128 8M */
      case 0xA2:  /* JYX68 8M */
        return 8 * 1024 * 1024;
      case 0x06:  /* D131CCS 16M */
      case 0x07:  /* D133ECS 16M */
        return 16 * 1024 * 1024;
      default:
        return 8 * 1024 * 1024;  /* 默认 8MB */
    }
}

static void d13x_xspi_wait_done(void)
{
  while (!(getreg32(XSPI_STATUS) & XSPI_STATUS_DONE));
}

static void d13x_psram_xspi_write_cmd(uint32_t cmd, uint32_t addr,
                                       uint8_t *data, int len)
{
  /* 等待空闲 */

  while (getreg32(XSPI_STATUS) & XSPI_STATUS_BUSY);

  /* 配置命令 */

  putreg32(cmd, XSPI_CMD);
  putreg32(addr, XSPI_ADDR);
  putreg32(len, XSPI_BCNT);

  /* 写入数据 */

  int i;
  for (i = 0; i < len; i++)
    {
      putreg32(data[i], XSPI_DATA);
    }

  /* 启动传输 */

  putreg32(1, XSPI_CTRL);

  /* 等待完成 */

  d13x_xspi_wait_done();
}

static void d13x_psram_xspi_read_cmd(uint32_t cmd, uint32_t addr,
                                      uint8_t *data, int len)
{
  /* 等待空闲 */

  while (getreg32(XSPI_STATUS) & XSPI_STATUS_BUSY);

  /* 配置命令 */

  putreg32(cmd, XSPI_CMD);
  putreg32(addr, XSPI_ADDR);
  putreg32(len, XSPI_BCNT);

  /* 启动传输 */

  putreg32(1, XSPI_CTRL);

  /* 等待完成 */

  d13x_xspi_wait_done();

  /* 读取数据 */

  int i;
  for (i = 0; i < len; i++)
    {
      data[i] = (uint8_t)getreg32(XSPI_DATA);
    }
}

static void d13x_psram_device_reset(void)
{
  /* 发送复位命令 */

  uint8_t cmd = PSRAM_CMD_RESET;
  d13x_psram_xspi_write_cmd(0xFF, 0, &cmd, 1);
}

static void d13x_psram_device_init(void)
{
  uint8_t data;

  /* 读取 MR4 检查当前配置 */

  d13x_psram_xspi_read_cmd(PSRAM_CMD_READ_MR, PSRAM_MR4, &data, 1);

  /* 配置 MR0: 设置 burst 长度和延迟 */

  data = 0x19;  /* Burst Length = 32, Latency = 3 */
  d13x_psram_xspi_write_cmd(PSRAM_CMD_WRITE_MR, PSRAM_MR0, &data, 1);

  /* 配置 MR4: 使能 XIP */

  data = 0x80;  /* Enable XIP */
  d13x_psram_xspi_write_cmd(PSRAM_CMD_WRITE_MR, PSRAM_MR4, &data, 1);
}

static void d13x_psram_xip_enable(void)
{
  /* 配置 XSPI 控制器为 XIP 模式 */

  uint32_t cfg = getreg32(XSPI_CFG);
  cfg |= (1 << 8);  /* XIP 模式 */
  cfg |= (1 << 9);  /* DDR 模式 */
  putreg32(cfg, XSPI_CFG);

  /* 配置 XIP 参数 */

  putreg32(0x00000000, XSPI_CFG2);  /* XIP 基地址 */
  putreg32(0x00000000, XSPI_CFG3);  /* XIP 大小 */
}

static uint32_t d13x_psram_verify(void)
{
  volatile uint32_t *psram = (volatile uint32_t *)D13X_PSRAM_BASE;
  uint32_t psram_size = d13x_psram_get_size();

  if (psram_size == 0)
    return 0;

  /* 写入测试模式 */

  psram[0] = 0x12345678;
  psram[1] = 0x9ABCDEF0;

  /* 读取并验证 */

  if (psram[0] != 0x12345678)
    return 0;

  if (psram[1] != 0x9ABCDEF0)
    return 0;

  /* 清除测试数据 */

  psram[0] = 0;
  psram[1] = 0;

  return psram_size;
}

static void d13x_psram_init(void)
{
  /* 首先验证 PSRAM 是否已初始化 */

  uint32_t psram_size = d13x_psram_verify();

  if (psram_size > 0)
    {
      /* PSRAM 已初始化，验证成功 */
      return;
    }

  /* PSRAM 未初始化，执行完整初始化 */

  /* 1. 使能 XSPI 时钟 (CMU_BASE + 0x460) */

  uint32_t reg = getreg32(D13X_CMU_BASE + 0x460);
  reg |= (1 << 13) | (1 << 12) | (1 << 8);
  putreg32(reg, D13X_CMU_BASE + 0x460);

  /* 2. 复位 XSPI 控制器 */

  putreg32(XSPI_CFG_RST, XSPI_CFG);
  while (getreg32(XSPI_CFG) & XSPI_CFG_RST);

  /* 3. 使能 XSPI 控制器 */

  putreg32(XSPI_CFG_EN | XSPI_CFG_CLK_EN, XSPI_CFG);

  /* 4. 复位 PSRAM 设备 */

  d13x_psram_device_reset();

  /* 5. 配置 PSRAM 设备 */

  d13x_psram_device_init();

  /* 6. 使能 XIP 模式 */

  d13x_psram_xip_enable();

  /* 7. 验证初始化 */

  d13x_psram_verify();
}

/****************************************************************************
 * 看门狗处理 (D13x)
 * WDT 基地址: 0x19000000 (来源: luban-lite aic_soc.h)
 ****************************************************************************/

static void d13x_watchdog_init(void)
{
  /* 禁用看门狗，防止启动过程中被复位
   * 写 WDOG_CTL 禁用看门狗 (bit 0 = EN, 写 0 禁用)
   */

  putreg32(0, WDOG_CTL);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: __start
 *
 * Description:
 *   D13x 系统复位入口
 *
 ****************************************************************************/

void __start(void)
{
  /* 清除 BSS 段 */

  uint32_t *ptr;

  for (ptr = _sbss; ptr < _ebss; ptr++)
    {
      *ptr = 0;
    }

  /* 拷贝 .data 段 */

  for (ptr = _sdata; ptr < _edata; ptr++)
    {
      *ptr = *(_eronly + (ptr - _sdata));
    }

  /* 禁用看门狗 */

  d13x_watchdog_init();

  /* 初始化系统时钟 */

  d13x_clock_init();

  /* 初始化 UART0 */

  d13x_uart_init();

  /* 初始化 PSRAM */

  d13x_psram_init();

  /* 打印启动信息 */

  putreg32('D', D13X_UART0_BASE + UART_RBR_THR_DLL);

  /* 启动 NuttX */

  nx_start();

  /* 不应到达此处 */

  for (; ; );
}

/****************************************************************************
 * vendor/artinchip/boards/d13x-hengshan-pi/scripts/ld.script
 *
 * D13x Hengshan Pi 链接脚本
 * 地址来源: luban-lite aic_soc.h + D13x User Manual
 *
 ****************************************************************************/

MEMORY
{
  flash (rx)  : ORIGIN = 0x60000000, LENGTH = 16M
  sram (rwx)  : ORIGIN = 0x30040000, LENGTH = 1M
  psram (rwx) : ORIGIN = 0x40000000, LENGTH = 8M
}

OUTPUT_ARCH(riscv)
EXTERN(_vectors)
ENTRY(_stext)

SECTIONS
{
    .text : {
        _stext = ABSOLUTE(.);
        *(.vectors)
        *(.text .text.*)
        *(.fixup)
        *(.gnu.warning)
        *(.rodata .rodata.*)
        *(.gnu.linkonce.t.*)
        *(.got)
        *(.gcc_except_table)
        *(.gnu.linkonce.r.*)
        _etext = ABSOLUTE(.);
    } > flash

    .init_section : {
        _sinit = ABSOLUTE(.);
        KEEP(*(SORT_BY_INIT_PRIORITY(.init_array.*) SORT_BY_INIT_PRIORITY(.ctors.*)))
        KEEP(*(.init_array EXCLUDE_FILE(*crtbegin.o *crtbegin?.o *crtend.o *crtend?.o) .ctors))
        _einit = ABSOLUTE(.);
    } > flash

    .tdata : {
        _stdata = ABSOLUTE(.);
        *(.tdata .tdata.* .gnu.linkonce.td.*);
        _etdata = ABSOLUTE(.);
    } > flash

    .tbss : {
        _stbss = ABSOLUTE(.);
        *(.tbss .tbss.* .gnu.linkonce.tb.* .tcommon);
        _etbss = ABSOLUTE(.);
    } > flash

    _eronly = ABSOLUTE(.);

    .data : {
        _sdata = ABSOLUTE(.);
        *(.data .data.*)
        *(.gnu.linkonce.d.*)
        CONSTRUCTORS
        . = ALIGN(4);
        _edata = ABSOLUTE(.);
    } > sram AT > flash

    .bss : {
        _sbss = ABSOLUTE(.);
        *(.bss .bss.*)
        *(.gnu.linkonce.b.*)
        *(COMMON)
        . = ALIGN(4);
        _ebss = ABSOLUTE(.);
    } > sram

    /* 调试段 */

    .stab 0 : { *(.stab) }
    .stabstr 0 : { *(.stabstr) }
    .stab.excl 0 : { *(.stab.excl) }
    .stab.exclstr 0 : { *(.stab.exclstr) }
    .stab.index 0 : { *(.stab.index) }
    .stab.indexstr 0 : { *(.stab.indexstr) }
    .comment 0 : { *(.comment) }
    .debug_abbrev 0 : { *(.debug_abbrev) }
    .debug_info 0 : { *(.debug_info) }
    .debug_line 0 : { *(.debug_line) }
    .debug_pubnames 0 : { *(.debug_pubnames) }
    .debug_aranges 0 : { *(.debug_aranges) }
}

/****************************************************************************
 * D13x tinySPL Bootloader - system.c
 *
 * 完整的系统初始化：时钟、UART、SPI Flash、PSRAM
 * 地址来源: luban-lite aic_soc.h + D13x User Manual
 *
 ****************************************************************************/

#include <stdint.h>
#include "d13x_boot.h"

/****************************************************************************
 * 寄存器访问宏
 ****************************************************************************/

#define getreg32(a)     (*(volatile uint32_t *)(a))
#define putreg32(v,a)   (*(volatile uint32_t *)(a) = (v))

/****************************************************************************
 * 外设基地址 (来源: luban-lite aic_soc.h)
 ****************************************************************************/

#define CMU_BASE        0x18020000
#define GPIO_BASE       0x18700000
#define UART0_BASE      0x18710000
#define XSPI_BASE       0x10300000  /* XSPI PSRAM 控制器 */
#define QSPI0_BASE      0x10400000  /* QSPI0 SPI Flash */
#define WDT_BASE        0x19000000  /* Watchdog */
#define SID_BASE        0x19010000  /* eFuse */

/****************************************************************************
 * PSRAM 配置 (D13x)
 ****************************************************************************/

#define PSRAM_BASE          0x40000000
#define PSRAM_SIZE          (8 * 1024 * 1024)  /* 8MB */

/* eFuse 寄存器 */

#define EFUSE_CMU_REG       (CMU_BASE + 0x904)
#define EFUSE_218_REG       (SID_BASE + 0x218)
#define EFUSE_224_REG       (SID_BASE + 0x224)

/* PSRAM 芯片 ID */

#define PSRAM_CHIP_APS3208K 0x80c9
#define PSRAM_CHIP_SCKW18   0xc59a
#define PSRAM_CHIP_APS12816 0xdd8d

/****************************************************************************
 * 时钟系统 (CMU)
 ****************************************************************************/

void d13x_clock_init(void)
{
  uint32_t reg;

  /* 打开 24MHz 振荡器 */

  reg = getreg32(CMU_BASE + 0x0A4);
  reg |= (1 << 1);
  putreg32(reg, CMU_BASE + 0x0A4);

  /* PLL 公共电路 LDO */

  reg = getreg32(CMU_BASE + 0x0A0);
  reg |= (1 << 31) | (1 << 0);
  putreg32(reg, CMU_BASE + 0x0A0);

  /* PLL_INT1 → 1.2GHz */

  putreg32(0x240C4040, CMU_BASE + 0x044);
  while (!(getreg32(CMU_BASE + 0x044) & (1 << 17)));

  /* PLL_INT0 → 480MHz */

  putreg32(0x240C4040, CMU_BASE + 0x040);
  while (!(getreg32(CMU_BASE + 0x040) & (1 << 17)));

  /* 总线时钟 */

  putreg32(0x00000001, CMU_BASE + 0x100);
  putreg32(0x00000001, CMU_BASE + 0x120);
  putreg32(0x00000100, CMU_BASE + 0x200);

  /* GPIO/UART 时钟 */

  reg = getreg32(CMU_BASE + 0x83C);
  reg |= (1 << 12) | (1 << 13);
  putreg32(reg, CMU_BASE + 0x83C);
  putreg32(0x00001001, CMU_BASE + 0x840);

  /* QSPI0 时钟: 释放复位 + 使能总线时钟 + 使能模块时钟 */

  putreg32((1 << 13) | (1 << 12) | (1 << 8), CMU_BASE + 0x460);
}

/****************************************************************************
 * UART 驱动 (UART0 基地址: 0x18710000)
 ****************************************************************************/

void d13x_uart_init(void)
{
  uint32_t divisor = 60000000 / (16 * 115200);
  putreg32(0, UART0_BASE + 0x0C);           /* LCR = 0 */
  putreg32(divisor & 0xFF, UART0_BASE + 0x00);  /* DLL */
  putreg32((divisor >> 8) & 0xFF, UART0_BASE + 0x04);  /* DLH */
  putreg32(0x07, UART0_BASE + 0x08);        /* FIFO: enable + reset */
  putreg32(0x03, UART0_BASE + 0x0C);        /* LCR: 8N1 */
}

void d13x_putc(char ch)
{
  while (!(getreg32(UART0_BASE + 0x14) & (1 << 5)));  /* LSR.THRE */
  putreg32((uint32_t)ch, UART0_BASE + 0x00);
}

int d13x_getc(void)
{
  while (!(getreg32(UART0_BASE + 0x14) & (1 << 0)));  /* LSR.DR */
  return (int)(getreg32(UART0_BASE + 0x00) & 0xFF);
}

int d13x_uart_rxready(void)
{
  return (getreg32(UART0_BASE + 0x14) & (1 << 0)) != 0;
}

/****************************************************************************
 * QSPI 控制器 (D13x)
 * QSPI0 基地址: 0x10400000 (来源: luban-lite aic_soc.h)
 ****************************************************************************/

#define QSPI_BASE      QSPI0_BASE
#define QSPI_VER       (QSPI_BASE + 0x000)
#define QSPI_CFG       (QSPI_BASE + 0x004)
#define QSPI_TCFG      (QSPI_BASE + 0x008)
#define QSPI_ICR       (QSPI_BASE + 0x010)
#define QSPI_ISTS      (QSPI_BASE + 0x014)
#define QSPI_FCTL      (QSPI_BASE + 0x018)
#define QSPI_FSTS      (QSPI_BASE + 0x01C)
#define QSPI_CCFG      (QSPI_BASE + 0x024)
#define QSPI_TXD       (QSPI_BASE + 0x200)
#define QSPI_RXD       (QSPI_BASE + 0x300)

/* QSPI_CFG bits */

#define QSPI_CFG_EN        (1 << 0)
#define QSPI_CFG_MASTER    (1 << 1)
#define QSPI_CFG_RST       (1 << 31)

/* QSPI_TCFG bits */

#define QSPI_TCFG_CPHA     (1 << 0)
#define QSPI_TCFG_CPOL     (1 << 1)
#define QSPI_TCFG_CS_LOW   (0 << 7)
#define QSPI_TCFG_CS_HIGH  (1 << 7)
#define QSPI_TCFG_CS_SW    (1 << 6)
#define QSPI_TCFG_START    (1 << 31)

/* QSPI_FSTS bits */

#define QSPI_FSTS_TD       (1 << 12)
#define QSPI_FSTS_TF_EMP   (1 << 5)
#define QSPI_FSTS_RF_RDY   (1 << 0)

static void d13x_spi_init(void)
{
  /* 复位控制器 */

  putreg32(QSPI_CFG_RST, QSPI_CFG);
  while (getreg32(QSPI_CFG) & QSPI_CFG_RST);

  /* 使能控制器 + 主机模式 */

  putreg32(QSPI_CFG_EN | QSPI_CFG_MASTER, QSPI_CFG);

  /* 时钟分频: SPI_CLK = src_clk / (2 * (CKDIV2 + 1))
   * src=480MHz, CKDIV2=15 → SPI_CLK = 480/(2*16) = 15MHz */

  putreg32(15, QSPI_CCFG);

  /* 传输配置: Mode 0 (CPOL=0, CPHA=0), 软件控制CS */

  putreg32(QSPI_TCFG_CS_SW | QSPI_TCFG_CS_HIGH, QSPI_TCFG);

  /* 复位 FIFO */

  putreg32((1 << 31) | (1 << 15), QSPI_FCTL);
}

static void d13x_spi_cs(int assert)
{
  uint32_t reg = getreg32(QSPI_TCFG);
  if (assert)
    reg &= ~QSPI_TCFG_CS_HIGH;
  else
    reg |= QSPI_TCFG_CS_HIGH;
  putreg32(reg, QSPI_TCFG);
}

static void d13x_spi_txrx(uint8_t *tx, uint8_t *rx, int len)
{
  int i;
  for (i = 0; i < len; i++)
    {
      /* 写入 TX FIFO */

      putreg32(tx ? tx[i] : 0, QSPI_TXD);

      /* 启动传输 */

      uint32_t tcfg = getreg32(QSPI_TCFG);
      putreg32(tcfg | QSPI_TCFG_START, QSPI_TCFG);

      /* 等待传输完成 */

      while (!(getreg32(QSPI_FSTS) & QSPI_FSTS_TD));

      /* 清除 TD 标志 (W1C) */

      putreg32(QSPI_FSTS_TD, QSPI_ISTS);

      /* 读取 RX FIFO */

      if (rx)
        rx[i] = (uint8_t)getreg32(QSPI_RXD);
    }
}

/****************************************************************************
 * SPI NOR Flash 驱动
 ****************************************************************************/

#define FLASH_WRITE_ENABLE    0x06
#define FLASH_READ_STATUS     0x05
#define FLASH_READ_DATA       0x03
#define FLASH_PAGE_PROGRAM    0x02
#define FLASH_SECTOR_ERASE    0x20
#define FLASH_READ_ID         0x9F

static void d13x_flash_write_enable(void)
{
  uint8_t cmd = FLASH_WRITE_ENABLE;
  d13x_spi_cs(1);
  d13x_spi_txrx(&cmd, 0, 1);
  d13x_spi_cs(0);
}

static void d13x_flash_wait_busy(void)
{
  uint8_t cmd = FLASH_READ_STATUS;
  uint8_t status;
  do {
    d13x_spi_cs(1);
    d13x_spi_txrx(&cmd, 0, 1);
    d13x_spi_txrx(0, &status, 1);
    d13x_spi_cs(0);
  } while (status & 0x01);
}

void d13x_flash_write(uint32_t addr, uint8_t *data, int len)
{
  uint8_t cmd[4];
  cmd[0] = FLASH_PAGE_PROGRAM;
  cmd[1] = (addr >> 16) & 0xFF;
  cmd[2] = (addr >> 8) & 0xFF;
  cmd[3] = addr & 0xFF;

  d13x_flash_write_enable();
  d13x_spi_cs(1);
  d13x_spi_txrx(cmd, 0, 4);
  d13x_spi_txrx(data, 0, len);
  d13x_spi_cs(0);
  d13x_flash_wait_busy();
}

void d13x_flash_erase_sector(uint32_t addr)
{
  uint8_t cmd[4];
  cmd[0] = FLASH_SECTOR_ERASE;
  cmd[1] = (addr >> 16) & 0xFF;
  cmd[2] = (addr >> 8) & 0xFF;
  cmd[3] = addr & 0xFF;

  d13x_flash_write_enable();
  d13x_spi_cs(1);
  d13x_spi_txrx(cmd, 0, 4);
  d13x_spi_cs(0);
  d13x_flash_wait_busy();
}

uint32_t d13x_flash_read_id(void)
{
  uint8_t cmd = FLASH_READ_ID;
  uint8_t id[3];
  uint32_t result;

  d13x_spi_cs(1);
  d13x_spi_txrx(&cmd, 0, 1);
  d13x_spi_txrx(0, id, 3);
  d13x_spi_cs(0);

  result = (id[0] << 16) | (id[1] << 8) | id[2];
  return result;
}

uint8_t d13x_flash_read(uint32_t addr, uint8_t *data, int len)
{
  uint8_t cmd[4];
  cmd[0] = FLASH_READ_DATA;
  cmd[1] = (addr >> 16) & 0xFF;
  cmd[2] = (addr >> 8) & 0xFF;
  cmd[3] = addr & 0xFF;

  d13x_spi_cs(1);
  d13x_spi_txrx(cmd, 0, 4);
  d13x_spi_txrx(0, data, len);
  d13x_spi_cs(0);

  return 0;
}

void d13x_flash_init(void)
{
  d13x_spi_init();
}

/****************************************************************************
 * PSRAM 驱动 (D13x)
 * XSPI 基地址: 0x10300000 (来源: luban-lite aic_soc.h)
 ****************************************************************************/

/* XSPI 控制器寄存器 */

#define XSPI_CFG            (XSPI_BASE + 0x000)
#define XSPI_TIMING         (XSPI_BASE + 0x004)
#define XSPI_CFG2           (XSPI_BASE + 0x008)
#define XSPI_CMD            (XSPI_BASE + 0x100)
#define XSPI_ADDR           (XSPI_BASE + 0x104)
#define XSPI_DATA           (XSPI_BASE + 0x108)
#define XSPI_CFG3           (XSPI_BASE + 0x10C)
#define XSPI_STATUS         (XSPI_BASE + 0x110)
#define XSPI_CTRL           (XSPI_BASE + 0x114)
#define XSPI_BCNT           (XSPI_BASE + 0x118)
#define XSPI_ACNT           (XSPI_BASE + 0x11C)
#define XSPI_DMA            (XSPI_BASE + 0x200)

/* XSPI 配置位 */

#define XSPI_CFG_EN         (1 << 0)
#define XSPI_CFG_RST        (1 << 1)
#define XSPI_CFG_CLK_EN     (1 << 2)

/* XSPI 状态位 */

#define XSPI_STATUS_BUSY    (1 << 0)
#define XSPI_STATUS_DONE    (1 << 1)

/* PSRAM 命令 */

#define PSRAM_CMD_RESET     0xFF
#define PSRAM_CMD_READ_ID   0x40
#define PSRAM_CMD_WRITE_MR  0xC0
#define PSRAM_CMD_READ_MR   0x40
#define PSRAM_CMD_WRITE     0x80
#define PSRAM_CMD_READ      0x00

/* PSRAM 模式寄存器 */

#define PSRAM_MR0           0x00
#define PSRAM_MR1           0x01
#define PSRAM_MR2           0x02
#define PSRAM_MR4           0x04

static uint32_t d13x_psram_read_efuse(uint32_t reg_addr)
{
  /* 使能 eFuse 时钟 */

  putreg32(0x1100, EFUSE_CMU_REG);

  /* 读取 eFuse 值 */

  uint32_t val = getreg32(reg_addr);

  /* 关闭 eFuse 时钟 */

  putreg32(0x0, EFUSE_CMU_REG);

  return val;
}

uint8_t d13x_psram_get_mark_id(void)
{
  uint32_t fuse_218 = d13x_psram_read_efuse(EFUSE_218_REG);
  return fuse_218 & 0xFF;
}

uint8_t d13x_psram_get_psram_id(void)
{
  uint32_t fuse_224 = d13x_psram_read_efuse(EFUSE_224_REG);
  return (fuse_224 >> 20) & 0xFF;
}

uint32_t d13x_psram_get_size(void)
{
  uint8_t mark_id = d13x_psram_get_mark_id();

  /* 根据 mark_id 确定 PSRAM 大小 */

  switch (mark_id)
    {
      case 0x00:  /* force use cfg0 */
        return 0;
      case 0x01:  /* D131BAS 4M */
        return 4 * 1024 * 1024;
      case 0x02:  /* D131BBS 8M */
      case 0x03:  /* D131CBS 8M */
      case 0x04:  /* D131EBS/D133EBS 8M */
      case 0x05:  /* D132ENS 8M */
      case 0xA1:  /* DR128 8M */
      case 0xA2:  /* JYX68 8M */
        return 8 * 1024 * 1024;
      case 0x06:  /* D131CCS 16M */
      case 0x07:  /* D133ECS 16M */
        return 16 * 1024 * 1024;
      default:
        return 8 * 1024 * 1024;  /* 默认 8MB */
    }
}

static void d13x_xspi_wait_done(void)
{
  while (!(getreg32(XSPI_STATUS) & XSPI_STATUS_DONE));
}

static void d13x_psram_xspi_write_cmd(uint32_t cmd, uint32_t addr,
                                       uint8_t *data, int len)
{
  /* 等待空闲 */

  while (getreg32(XSPI_STATUS) & XSPI_STATUS_BUSY);

  /* 配置命令 */

  putreg32(cmd, XSPI_CMD);
  putreg32(addr, XSPI_ADDR);
  putreg32(len, XSPI_BCNT);

  /* 写入数据 */

  int i;
  for (i = 0; i < len; i++)
    {
      putreg32(data[i], XSPI_DATA);
    }

  /* 启动传输 */

  putreg32(1, XSPI_CTRL);

  /* 等待完成 */

  d13x_xspi_wait_done();
}

static void d13x_psram_xspi_read_cmd(uint32_t cmd, uint32_t addr,
                                      uint8_t *data, int len)
{
  /* 等待空闲 */

  while (getreg32(XSPI_STATUS) & XSPI_STATUS_BUSY);

  /* 配置命令 */

  putreg32(cmd, XSPI_CMD);
  putreg32(addr, XSPI_ADDR);
  putreg32(len, XSPI_BCNT);

  /* 启动传输 */

  putreg32(1, XSPI_CTRL);

  /* 等待完成 */

  d13x_xspi_wait_done();

  /* 读取数据 */

  int i;
  for (i = 0; i < len; i++)
    {
      data[i] = (uint8_t)getreg32(XSPI_DATA);
    }
}

static void d13x_psram_device_reset(void)
{
  /* 发送复位命令 */

  uint8_t cmd = PSRAM_CMD_RESET;
  d13x_psram_xspi_write_cmd(0xFF, 0, &cmd, 1);
}

static void d13x_psram_device_init(void)
{
  uint8_t data;

  /* 读取 MR4 检查配置 */

  d13x_psram_xspi_read_cmd(PSRAM_CMD_READ_MR, PSRAM_MR4, &data, 1);

  /* 配置 MR0: 设置 burst 长度和延迟 */

  data = 0x19;  /* Burst Length = 32, Latency = 3 */
  d13x_psram_xspi_write_cmd(PSRAM_CMD_WRITE_MR, PSRAM_MR0, &data, 1);

  /* 配置 MR4: 使能 XIP */

  data = 0x80;  /* Enable XIP */
  d13x_psram_xspi_write_cmd(PSRAM_CMD_WRITE_MR, PSRAM_MR4, &data, 1);
}

static void d13x_psram_xip_enable(void)
{
  /* 配置 XSPI 控制器为 XIP 模式 */

  uint32_t cfg = getreg32(XSPI_CFG);
  cfg |= (1 << 8);  /* XIP 模式 */
  cfg |= (1 << 9);  /* DDR 模式 */
  putreg32(cfg, XSPI_CFG);

  /* 配置 XIP 参数 */

  putreg32(0x00000000, XSPI_CFG2);  /* XIP 基地址 */
  putreg32(0x00000000, XSPI_CFG3);  /* XIP 大小 */
}

uint32_t d13x_psram_verify(void)
{
  volatile uint32_t *psram = (volatile uint32_t *)PSRAM_BASE;
  uint32_t psram_size = d13x_psram_get_size();

  if (psram_size == 0)
    return 0;  /* 无法确定 PSRAM 大小 */

  /* 写入测试模式 */

  psram[0] = 0x12345678;
  psram[1] = 0x9ABCDEF0;

  /* 读取并验证 */

  if (psram[0] != 0x12345678)
    return 0;  /* PSRAM 读写失败 */

  if (psram[1] != 0x9ABCDEF0)
    return 0;  /* PSRAM 读写失败 */

  /* 清除测试数据 */

  psram[0] = 0;
  psram[1] = 0;

  return psram_size;
}

void d13x_psram_init(void)
{
  /* 首先验证 PSRAM 是否已初始化 */

  uint32_t psram_size = d13x_psram_verify();

  if (psram_size > 0)
    {
      /* PSRAM 已初始化，验证成功 */

      print_str("PSRAM: Already initialized (");
      print_hex(psram_size);
      print_str(" bytes)\r\n");
      return;
    }

  /* PSRAM 未初始化，执行完整初始化 */

  print_str("PSRAM: Initializing...\r\n");

  /* 1. 使能 XSPI 时钟 (CMU_BASE + 0x460) */

  uint32_t reg = getreg32(CMU_BASE + 0x460);
  reg |= (1 << 13) | (1 << 12) | (1 << 8);
  putreg32(reg, CMU_BASE + 0x460);

  /* 2. 复位 XSPI 控制器 */

  putreg32(XSPI_CFG_RST, XSPI_CFG);
  while (getreg32(XSPI_CFG) & XSPI_CFG_RST);

  /* 3. 使能 XSPI 控制器 */

  putreg32(XSPI_CFG_EN | XSPI_CFG_CLK_EN, XSPI_CFG);

  /* 4. 复位 PSRAM 设备 */

  d13x_psram_device_reset();

  /* 5. 配置 PSRAM 设备 */

  d13x_psram_device_init();

  /* 6. 使能 XIP 模式 */

  d13x_psram_xip_enable();

  /* 7. 验证初始化 */

  psram_size = d13x_psram_verify();

  if (psram_size > 0)
    {
      print_str("PSRAM: OK (");
      print_hex(psram_size);
      print_str(" bytes)\r\n");
    }
  else
    {
      print_str("PSRAM: Init failed!\r\n");
    }
}

