static void d13x_clock_init(void)
{
  uint32_t reg;

  /* 1. 打开 24MHz 振荡器 (PLL_IN bit1 = OSC24M_ENOSC24M) */

  reg = getreg32(CMU_PLL_IN);
  reg |= (1 << 1);
  putreg32(reg, CMU_PLL_IN);

  /* 2. PLL 公共电路 LDO (PLL_COM bit31=COMMON_GATE, bit0=LDO_EN) */

  reg = getreg32(CMU_PLL_COM);
  reg |= (1 << 31) | (1 << 0);
  putreg32(reg, CMU_PLL_COM);

  /* 3. 使能 PLL_INT1 → 1.2GHz (N=49, 24*(49+1)=1200MHz)
   * PLL_INT1_GEN: FACTOR_N=0x31(49) at bits[15:8], ENABLE at bit0
   * 复位默认 FACTOR_N=0x31 即 1.2GHz，此处显式使能
   */

  reg = getreg32(CMU_PLL_INT1_GEN);
  reg |= PLL_GEN_ENABLE;
  putreg32(reg, CMU_PLL_INT1_GEN);

  /* 等待 PLL 锁定 (PLL_INT1_GEN bit17 = PLL_LOCK) */

  while (!(getreg32(CMU_PLL_INT1_GEN) & PLL_GEN_LOCK_BIT));

  /* 4. 使能 PLL_INT0 → 480MHz (N=19, 24*(19+1)=480MHz)
   * 需要设置 FACTOR_N=0x13(19) 在 PLL_INT0_GEN
   */

  reg = getreg32(CMU_PLL_INT0_GEN);
  reg &= ~PLL_GEN_FACTOR_N_MASK;
  reg |= (19 << PLL_GEN_FACTOR_N_SHIFT);  /* N=19 → 480MHz */
  reg |= PLL_GEN_ENABLE;
  putreg32(reg, CMU_PLL_INT0_GEN);

  /* 等待 PLL 锁定 (PLL_INT0_GEN bit17 = PLL_LOCK) */

  while (!(getreg32(CMU_PLL_INT0_GEN) & PLL_GEN_LOCK_BIT));

  /* 5. 总线时钟: AXI/AHB = 200MHz
   * CLK_AXI_AHB: bit8=1(PLL_INT1源), DIV=5 → 1200/(5+1)=200MHz
   */

  putreg32(CLK_SRC_PLL_INT1 | 5, CMU_CLK_AXI_AHB);

  /* 6. APB0 = 100MHz
   * CLK_APB0: bit8=1(PLL_INT1源), DIV=11 → 1200/(11+1)=100MHz
   */

  putreg32(CLK_SRC_PLL_INT1 | 11, CMU_CLK_APB0);

  /* 7. CPU 时钟: 480MHz
   * CLK_CPU: bit8=1(PLL_INT0源), DIV=0 → 480/(0+1)=480MHz
   */

  putreg32(CLK_SRC_PLL_INT0 | 0, CMU_CLK_CPU);

  /* 8. 打开 GPIO 时钟 (bit13=MOD_RSTN, bit12=MOD_BUS_EN) */

  reg = getreg32(CMU_CLK_GPIO);
  reg |= (1 << 13) | (1 << 12);
  putreg32(reg, CMU_CLK_GPIO);

  /* 9. 打开 UART0 时钟: 60MHz
   * CLK_UART0: bit13=MOD_RSTN, bit12=MOD_BUS_EN, bit8=MOD_CLK_EN
   * DIV=19 → 1200/(19+1)=60MHz
   */

  putreg32(UART_CLK_MOD_RSTN | UART_CLK_MOD_BUS_EN | UART_CLK_MOD_CLK_EN | 19,
           CMU_CLK_UART0);
}

