static int d13x_uart0_handler(int irq, FAR void *context, FAR void *arg)
{
  FAR struct uart_dev_s *dev = arg;

  /* 处理接收中断 */

  while (getreg32(D13X_UART0_BASE + UART_LSR) & UART_LSR_DR)
    {
      /* 读取字符并放入缓冲区 */

      volatile uint32_t thr = getreg32(D13X_UART0_BASE + UART_RBR_THR_DLL);
      (void)thr;
    }

  /* 通知上层有数据可读 */

  uart_recvchars(dev);

  return OK;
}

