static void d13x_uart_init(void)
{
  uint32_t divisor;

  /* 配置 UART0 引脚复用: PA0→TX, PA1→RX (PIN_FUN=5) */
  /* TODO: 配置 GPIO 引脚复用寄存器 (需要查看 luban-lite pinmux) */

  /* 配置波特率 115200: divisor = 60MHz / (16 × 115200) ≈ 32 */

  divisor = D13X_UART0_FREQ / (16 * D13X_UART0_BAUDRATE);

  /* 禁用 UART */

  putreg32(0, D13X_UART0_BASE + UART_LCR);

  /* 配置波特率 */

  putreg32(divisor & 0xFF, D13X_UART0_BASE + UART_RBR_THR_DLL);
  putreg32((divisor >> 8) & 0xFF, D13X_UART0_BASE + UART_DLH);

  /* 使能 FIFO */

  putreg32(UART_FCR_FIFOE | UART_FCR_RFIFOR | UART_FCR_XFIFOR,
           D13X_UART0_BASE + UART_FCR);

  /* 配置 8N1: 8 数据位, 1 停止位, 无校验 */

  putreg32(0x03, D13X_UART0_BASE + UART_LCR);
}

