void d13x_clock_init(void)
{
  uint32_t reg;

  /* 打开 24MHz 振荡器 (PLL_IN bit1) */

  reg = getreg32(CMU_BASE + 0x0A4);
  reg |= (1 << 1);
  putreg32(reg, CMU_BASE + 0x0A4);

  /* PLL 公共电路 LDO (PLL_COM bit31 + bit0) */

  reg = getreg32(CMU_BASE + 0x0A0);
  reg |= (1 << 31) | (1 << 0);
  putreg32(reg, CMU_BASE + 0x0A0);

  /* 使能 PLL_INT1 → 1.2GHz (PLL_INT1_GEN bit0=ENABLE, bit17=LOCK)
   * 默认 FACTOR_N=0x31(49), 24*(49+1)=1200MHz
   */

  reg = getreg32(CMU_BASE + 0x004);  /* PLL_INT1_GEN */
  reg |= (1 << 0);  /* ENABLE */
  putreg32(reg, CMU_BASE + 0x004);
  while (!(getreg32(CMU_BASE + 0x004) & (1 << 17)));

  /* 使能 PLL_INT0 → 480MHz (设置 FACTOR_N=19, 24*(19+1)=480MHz) */

  reg = getreg32(CMU_BASE + 0x000);  /* PLL_INT0_GEN */
  reg &= ~(0xFF << 8);  /* 清除 FACTOR_N */
  reg |= (19 << 8);     /* N=19 → 480MHz */
  reg |= (1 << 0);      /* ENABLE */
  putreg32(reg, CMU_BASE + 0x000);
  while (!(getreg32(CMU_BASE + 0x000) & (1 << 17)));

  /* AXI/AHB = 200MHz (PLL_INT1 源, div=5 → 1200/6=200MHz) */

  putreg32((1 << 8) | 5, CMU_BASE + 0x100);

  /* APB0 = 100MHz (PLL_INT1 源, div=11 → 1200/12=100MHz) */

  putreg32((1 << 8) | 11, CMU_BASE + 0x120);

  /* CPU = 480MHz (PLL_INT0 源, div=0 → 480MHz) */

  putreg32((1 << 8) | 0, CMU_BASE + 0x200);

  /* GPIO 时钟 */

  reg = getreg32(CMU_BASE + 0x83C);
  reg |= (1 << 12) | (1 << 13);
  putreg32(reg, CMU_BASE + 0x83C);

  /* UART0 = 60MHz (PLL_INT1 源, div=19, 含 MOD_BUS_EN) */

  putreg32((1 << 13) | (1 << 12) | (1 << 8) | 19, CMU_BASE + 0x840);

  /* QSPI0 时钟: 释放复位 + 使能总线时钟 + 使能模块时钟 (CMU_BASE + 0x460) */

  putreg32((1 << 13) | (1 << 12) | (1 << 8), CMU_BASE + 0x460);

  /* XSPI 时钟: 释放复位 + 使能总线时钟 + 使能模块时钟 (CMU_BASE + 0x45C) */

  putreg32((1 << 13) | (1 << 12) | (1 << 8), CMU_BASE + 0x45C);
}

