void d13x_flash_erase_sector(uint32_t addr)
{
  uint8_t cmd[4];
  cmd[0] = FLASH_SECTOR_ERASE;
  cmd[1] = (addr >> 16) & 0xFF;
  cmd[2] = (addr >> 8) & 0xFF;
  cmd[3] = addr & 0xFF;

