{
  uint32_t reg;

  /* 1. 打开 24MHz 振荡器 */

  reg = getreg32(CMU_PLL_IN);
  reg |= (1 << 1);
  putreg32(reg, CMU_PLL_IN);

  /* 2. PLL 公共电路 LDO */

  reg = getreg32(CMU_PLL_COM);
  reg |= (1 << 31) | (1 << 0);
  putreg32(reg, CMU_PLL_COM);

  /* 3. 使能 PLL_INT1 → 1.2GHz (N=49) */

  reg = getreg32(CMU_PLL_INT1_GEN);
  reg |= PLL_GEN_ENABLE;

