{
    "spi-nor": { // Device, The name should be the same with string in image:info:media:type
        "size": "16m", // Size of SPI NOR Flash
        "partitions": {
            "spl":        { "size": "256k" },
            "os":         { "size": "2m" },
            "rodata":     { "size": "6m" },
            "data":       { "size": "7m" }
        },
    },
    "image": {
        "info": { // Header information about image
            "platform": "d13x",
            "product": "hengshan-pi",
            "version": "1.0.0",
            "media": {
                "type": "spi-nor",
                "device_id": 0,
            }
        },
        "updater": { // Image writer which is downloaded to RAM by USB/UART
            "spl": {
                "file": "bootloader.aic",
                "attr": ["required", "run"],
                "ram": "0x30100000"
            },
        },
        "target": { // Image components which will be burn to device's partitions
            "spl": {
                "file": "bootloader.aic",
                "attr": ["mtd", "required"],
                "part": ["spl"]
            },
            "os": {
                "file": "d13x_os.itb",
                "attr": ["mtd", "required"],
                "part": ["os"]
            },
            "rodata": {
                "file": "rodata.fatfs",
                "attr": ["mtd", "optional"],
                "part": ["rodata"]
            },
            "data": {
                "file": "data.lfs",
                "attr": ["mtd", "optional"],
                "part": ["data"]
            },
        },
    },
    "pre-process": { // Pre-proccess to generate image components from raw data
        "aicimage": { // Create aic boot image
            "loader.aic": {
                "head_ver": "0x00010001",
                "loader": {
                    "file": "bootloader.bin",
                    "load address": "0x30100000",
                    "entry point": "0x30100000"
                },
            },
        },
        "concatenate": { // cat files in order
            "bootloader.aic": ["loader.aic"],
        },
        "itb": { // Create itb image from its
            "d13x_os.itb": {
                "its": "d13x_os.its"
            },
        },
    },
}

