/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_fb.c
 *
 * D13x 最小 Framebuffer 驱动 (测试用)
 * 仅用于验证 LCD 控制器是否工作
 *
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/irq.h>
#include <nuttx/arch.h>
#include <nuttx/video/fb.h>
#include <nuttx/kmalloc.h>
#include "chip.h"

/****************************************************************************
 * D13x LCD 控制器寄存器 (来源: D13x User Manual)
 ****************************************************************************/

#define LCD_CTRL        (D13X_LCD_BASE + 0x000)
#define LCD_INT         (D13X_LCD_BASE + 0x004)
#define LCD_STATUS      (D13X_LCD_BASE + 0x008)
#define LCD_timing0     (D13X_LCD_BASE + 0x040)
#define LCD_timing1     (D13X_LCD_BASE + 0x044)
#define LCD_timing2     (D13X_LCD_BASE + 0x048)
#define LCD_DPI         (D13X_LCD_BASE + 0x060)
#define LCD_FIFOTH      (D13X_LCD_BASE + 0x064)
#define LCD_IOCTL       (D13X_LCD_BASE + 0x068)
#define LCD_CLK         (D13X_LCD_BASE + 0x080)
#define LCD_SIZE        (D13X_LCD_BASE + 0x0C0)
#define LCD_IF          (D13X_LCD_BASE + 0x0C4)
#define LCD_LVDS        (D13X_LCD_BASE + 0x0F0)

/* LCD 寄存器位定义 */

#define LCD_CTRL_EN             (1 << 0)
#define LCD_CTRL_RESET          (1 << 1)
#define LCD_INT_FRM_DONE        (1 << 0)
#define LCD_STATUS_BUSY         (1 << 0)

/* LCD 接口类型 */

#define LCD_IF_RGB666           0
#define LCD_IF_RGB888           1
#define LCD_IF_MIPI_DSI         2
#define LCD_IF_LVDS             3
#define LCD_IF_DBI              4

/****************************************************************************
 * Framebuffer 驱动
 ****************************************************************************/

static struct fb_vtable_s g_fb_vtable;
static struct fb_videoinfo_s g_videoinfo;
static struct fb_planeinfo_s g_planeinfo;
static uint32_t *g_framebuffer;
static int g_fb_initialized = 0;

/****************************************************************************
 * LCD 初始化 (最小化)
 ****************************************************************************/

static void d13x_lcd_init(int width, int height)
{
  /* 复位 LCD 控制器 */

  putreg32(LCD_CTRL_RESET, LCD_CTRL);

  /* 等待复位完成 */

  while (getreg32(LCD_STATUS) & LCD_STATUS_BUSY);

  /* 配置时钟: PLL_INT1 / 10 = 120MHz */

  putreg32(0x00000009, LCD_CLK);

  /* 配置显示尺寸 */

  putreg32((height << 16) | width, LCD_SIZE);

  /* 配置时序 (简化: 用于 RGB888 接口) */

  /* timing0: hsync, vsync, hbp, vbp */

  putreg32((10 << 0) | (10 << 10) | (40 << 20) | (40 << 30), LCD_timing0);

  /* timing1: hfp, vfp */

  putreg32((20 << 0) | (20 << 16), LCD_timing1);

  /* timing2: width, height */

  putreg32((width << 0) | (height << 16), LCD_timing2);

  /* 配置接口为 RGB888 */

  putreg32(LCD_IF_RGB888, LCD_IF);

  /* 使能 LCD 控制器 */

  putreg32(LCD_CTRL_EN, LCD_CTRL);
}

/****************************************************************************
 * Framebuffer 操作回调
 ****************************************************************************/

static int d13x_fb_getvideoinfo(FAR struct fb_vtable_s *vtable,
                                 FAR struct fb_videoinfo_s *vinfo)
{
  memcpy(vinfo, &g_videoinfo, sizeof(struct fb_videoinfo_s));
  return OK;
}

static int d13x_fb_getplaneinfo(FAR struct fb_vtable_s *vtable,
                                 int planeno,
                                 FAR struct fb_planeinfo_s *pinfo)
{
  memcpy(pinfo, &g_planeinfo, sizeof(struct fb_planeinfo_s));
  return OK;
}

static int d13x_fb_open(FAR struct fb_vtable_s *vtable)
{
  return OK;
}

static int d13x_fb_close(FAR struct fb_vtable_s *vtable)
{
  return OK;
}

static int d13x_fb_updatearea(FAR struct fb_vtable_s *vtable,
                               FAR struct fb_area_s *area,
                               FAR const uint8_t *buffer)
{
  /* 简化实现: 将数据拷贝到 framebuffer */

  if (buffer && g_framebuffer)
    {
      int x, y;
      int bpp = g_planeinfo.bpp / 8;
      int fb_stride = g_videoinfo.xres * bpp;

      for (y = area->y1; y <= area->y2 && y < g_videoinfo.yres; y++)
        {
          int src_offset = (y - area->y1) * area->stride;
          int dst_offset = y * fb_stride + area->x1 * bpp;
          int copy_len = (area->x2 - area->x1 + 1) * bpp;

          memcpy((uint8_t *)g_framebuffer + dst_offset,
                 buffer + src_offset, copy_len);
        }
    }

  return OK;
}

/****************************************************************************
 * 显示初始化入口
 ****************************************************************************/

int d13x_fb_initialize(int width, int height, int bpp)
{
  int fb_size;

  if (g_fb_initialized)
    return OK;

  /* 分配 framebuffer 内存 */

  fb_size = width * height * (bpp / 8);
  g_framebuffer = kmm_zalloc(fb_size);
  if (!g_framebuffer)
    {
      return -ENOMEM;
    }

  /* 配置 videoinfo */

  g_videoinfo.xres = width;
  g_videoinfo.yres = height;
  g_videoinfo.nplanes = 1;

  /* 配置 planeinfo */

  g_planeinfo.bpp = bpp;
  g_planeinfo.stride = width * (bpp / 8);
  g_planeinfo.buffer = (uint8_t *)g_framebuffer;
  g_planeinfo.display = 0;

  /* 初始化 LCD 控制器 */

  d13x_lcd_init(width, height);

  /* 填充测试图案: 彩色条纹 */

  int i;
  int pixels_per_color = width / 6;
  uint32_t colors[] = {0xFF0000, 0x00FF00, 0x0000FF, 0xFFFF00, 0xFF00FF, 0x00FFFF};

  for (i = 0; i < width * height; i++)
    {
      int x = i % width;
      int color_idx = x / pixels_per_color;
      if (color_idx >= 6) color_idx = 5;
      g_framebuffer[i] = colors[color_idx];
    }

  /* 注册 framebuffer 设备 */

  g_fb_vtable.getvideoinfo = d13x_fb_getvideoinfo;
  g_fb_vtable.getplaneinfo = d13x_fb_getplaneinfo;
  g_fb_vtable.open = d13x_fb_open;
  g_fb_vtable.close = d13x_fb_close;
  g_fb_vtable.updatearea = d13x_fb_updatearea;

  fb_register(0, 0);

  g_fb_initialized = 1;

  return OK;
}

