  g_planeinfo.xres_virtual = 480;
  g_planeinfo.yres_virtual = 480;

  d13x_lcd_init(480, 480);

  pixels_per_color = 480 / 6;
  colors[0] = 0x0000FF; colors[1] = 0x00FF00; colors[2] = 0xFF0000;
  colors[3] = 0x00FFFF; colors[4] = 0xFF00FF; colors[5] = 0xFFFF00;

  for (i = 0; i < 480 * 480; i++)
    {
      int x = i % 480;
      int idx = x / pixels_per_color;
      if (idx >= 6) idx = 5;
      g_framebuffer[i] = colors[idx];
    }

  g_fb_vtable.getvideoinfo = d13x_fb_getvideoinfo;
  g_fb_vtable.getplaneinfo = d13x_fb_getplaneinfo;
  g_fb_vtable.open = d13x_fb_open;
  g_fb_vtable.close = d13x_fb_close;

  g_fb_initialized = 1;
  return OK;
}

FAR struct fb_vtable_s *up_fbgetvplane(int display, int vplane)
{
  if (vplane == 0 && g_fb_initialized) return &g_fb_vtable;
  return NULL;
}

void up_fbuninitialize(int display) {}

