/* LCD 面板 GPIO 定义 (需要根据实际硬件调整) */

#define LCD_RESET_GPIO    0  /* PA0 - LCD 复位脚 */
#define LCD_BACKLIGHT_GPIO 1  /* PA1 - 背光控制 */

/****************************************************************************
 * LCD 面板初始化序列
 ****************************************************************************/

static void d13x_lcd_panel_init(void)
{
  /* 配置 LCD 复位脚为输出 */

  gpio_direction_output(LCD_RESET_GPIO, 0);

  /* 复位 LCD 面板 */

  gpio_set_value(LCD_RESET_GPIO, 0);

  /* 等待复位完成 */

  up_mdelay(20);

  gpio_set_value(LCD_RESET_GPIO, 1);

  /* 等待面板稳定 */

  up_mdelay(120);

  /* 开启背光 */

  gpio_direction_output(LCD_BACKLIGHT_GPIO, 1);
  gpio_set_value(LCD_BACKLIGHT_GPIO, 1);
}

