{
}
#endif

#ifdef CONFIG_BOARD_LATE_INITIALIZE
void board_late_initialize(void)
{
}
#endif

int board_app_initialize(uintptr_t arg)
{
  /* 初始化 LCD 面板 */

  d13x_lcd_panel_init();

  /* 注册 framebuffer 设备 */

#ifdef CONFIG_VIDEO_FB
  fb_register(0, 0);
#endif

  return 0;
}

