/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_i2c.c
 *
 * D13x I2C 驱动
 *
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/irq.h>
#include <nuttx/arch.h>
#include <nuttx/i2c/i2c_master.h>
#include "chip.h"

#define I2C0_CR      (D13X_I2C0_BASE + 0x000)
#define I2C0_SR      (D13X_I2C0_BASE + 0x004)
#define I2C0_ADDR    (D13X_I2C0_BASE + 0x008)
#define I2C0_DX      (D13X_I2C0_BASE + 0x00C)
#define I2C0_CLKL    (D13X_I2C0_BASE + 0x010)
#define I2C0_CLKH    (D13X_I2C0_BASE + 0x014)

#define I2C_CR_ENABLE    (1 << 0)
#define I2C_CR_START     (1 << 1)
#define I2C_CR_STOP      (1 << 2)
#define I2C_CR_ACK       (1 << 3)
#define I2C_CR_NACK      (1 << 4)
#define I2C_CR_RW        (1 << 5)

#define I2C_SR_BUSY      (1 << 0)
#define I2C_SR_ACK       (1 << 1)
#define I2C_SR_NACK      (1 << 2)
#define I2C_SR_TFE       (1 << 3)
#define I2C_SR_RFNE      (1 << 4)

static struct i2c_master_s g_i2c0_dev;

static int d13x_i2c_transfer(FAR struct i2c_master_s *dev,
                              FAR struct i2c_msg_s *msgs, int count)
{
  int i;

  putreg32(I2C_CR_ENABLE, I2C0_CR);

  for (i = 0; i < count; i++)
    {
      FAR struct i2c_msg_s *msg = &msgs[i];
      uint32_t addr_byte = (msg->addr << 1) |
                           ((msg->flags & I2C_M_READ) ? I2C_CR_RW : 0);

      putreg32(I2C_CR_START | I2C_CR_ENABLE | addr_byte, I2C0_CR);
      while (getreg32(I2C0_SR) & I2C_SR_BUSY);

      if (getreg32(I2C0_SR) & I2C_SR_NACK)
        {
          putreg32(I2C_CR_STOP | I2C_CR_ENABLE, I2C0_CR);
          return -ENXIO;
        }

      int j;
      if (msg->flags & I2C_M_READ)
        {
          for (j = 0; j < msg->length; j++)
            {
              uint32_t cr = I2C_CR_ENABLE;
              if (j < msg->length - 1)
                cr |= I2C_CR_ACK;
              else
                cr |= I2C_CR_NACK;
              putreg32(cr, I2C0_CR);
              while (!(getreg32(I2C0_SR) & I2C_SR_RFNE));
              msg->buffer[j] = getreg32(I2C0_DX) & 0xFF;
            }
        }
      else
        {
          for (j = 0; j < msg->length; j++)
            {
              while (!(getreg32(I2C0_SR) & I2C_SR_TFE));
              putreg32(msg->buffer[j], I2C0_DX);
            }
        }

      if (i == count - 1 || !(msg->flags & I2C_M_NOSTOP))
        {
          putreg32(I2C_CR_STOP | I2C_CR_ENABLE, I2C0_CR);
        }
    }

  return OK;
}

static int d13x_i2c_setup(FAR struct i2c_master_s *dev)
{
  uint32_t pclk = D13X_APB0_FREQ;
  uint32_t div = pclk / (2 * 400000);

  putreg32(div & 0xFFFF, I2C0_CLKL);
  putreg32(div & 0xFFFF, I2C0_CLKH);
  return OK;
}

static int d13x_i2c_shutdown(FAR struct i2c_master_s *dev)
{
  return OK;
}

static const struct i2c_ops_s g_d13x_i2c_ops =
{
  .transfer = d13x_i2c_transfer,
  .setup = d13x_i2c_setup,
  .shutdown = d13x_i2c_shutdown,
};

FAR struct i2c_master_s *d13x_i2c0_initialize(void)
{
  g_i2c0_dev.ops = &g_d13x_i2c_ops;
  return &g_i2c0_dev;
}

