 *
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/irq.h>
#include <nuttx/arch.h>
#include <nuttx/video/fb.h>
#include <nuttx/kmalloc.h>
#include <string.h>
#include "chip.h"

/* LVDS 控制器寄存器 (来源: D13x User Manual) */

#define LVDS_CTL        (D13X_LVDS_BASE + 0x000)
#define LVDS_CFG        (D13X_LVDS_BASE + 0x004)
#define LVDS_CLK        (D13X_LVDS_BASE + 0x008)
#define LVDS_INT        (D13X_LVDS_BASE + 0x00C)
#define LVDS_STATUS     (D13X_LVDS_BASE + 0x010)

/* LVDS_CTL 位定义 */

#define LVDS_CTL_EN             (1 << 0)
#define LVDS_CTL_RESET          (1 << 1)

/* LVDS 面板参数: 1024x600 */

#define PANEL_HRES              1024
#define PANEL_VRES              600
#define PANEL_PCLK              51200000  /* 51.2MHz 像素时钟 */

/* LVDS 时序参数 (1024x600 面板典型值) */

#define LVDS_HSYNC_WIDTH        10
#define LVDS_HBP                160
#define LVDS_HFP                160
#define LVDS_VSYNC_WIDTH        5
#define LVDS_VBP                23
#define LVDS_VFP                12

/****************************************************************************
 * Framebuffer 驱动
 ****************************************************************************/

static struct fb_vtable_s g_fb_vtable;
static struct fb_videoinfo_s g_videoinfo;
static struct fb_planeinfo_s g_planeinfo;
static uint32_t *g_framebuffer;
static int g_fb_initialized = 0;

/****************************************************************************
 * LVDS 初始化
 ****************************************************************************/

static void d13x_lvds_init(int width, int height)
{
  /* 复位 LVDS 控制器 */

  putreg32(LVDS_CTL_RESET, LVDS_CTL);

  /* 等待复位完成 */

  up_mdelay(10);

  /* 配置 LVDS 时钟 */

  putreg32(0x00000001, LVDS_CLK);

  /* 配置 LVDS */

  putreg32(0x00000001, LVDS_CFG);

  /* 使能 LVDS 控制器 */

  putreg32(LVDS_CTL_EN, LVDS_CTL);
}

/****************************************************************************
 * Framebuffer 操作回调
 ****************************************************************************/

static int d13x_lvds_getvideoinfo(FAR struct fb_vtable_s *vtable,
                                   FAR struct fb_videoinfo_s *vinfo)
{
  memcpy(vinfo, &g_videoinfo, sizeof(struct fb_videoinfo_s));
  return OK;
}

static int d13x_lvds_getplaneinfo(FAR struct fb_vtable_s *vtable,
                                   int planeno,
                                   FAR struct fb_planeinfo_s *pinfo)
{
  memcpy(pinfo, &g_planeinfo, sizeof(struct fb_planeinfo_s));
  return OK;
}

static int d13x_lvds_open(FAR struct fb_vtable_s *vtable) { return OK; }
static int d13x_lvds_close(FAR struct fb_vtable_s *vtable) { return OK; }

/****************************************************************************
 * NuttX 架构层 framebuffer 函数
 ****************************************************************************/

int up_fbinitialize(int display)
{
  int fb_size, i, pixels_per_color;
  uint32_t colors[6];

  if (g_fb_initialized) return OK;

  fb_size = PANEL_HRES * PANEL_VRES * 4;
  g_framebuffer = kmm_zalloc(fb_size);
  if (!g_framebuffer) return -ENOMEM;

  g_videoinfo.xres = PANEL_HRES;
  g_videoinfo.yres = PANEL_VRES;
  g_videoinfo.nplanes = 1;
  g_videoinfo.fmt = FB_FMT_RGB32;

  g_planeinfo.bpp = 32;
  g_planeinfo.stride = PANEL_HRES * 4;
  g_planeinfo.fbmem = (FAR void *)g_framebuffer;
  g_planeinfo.fblen = fb_size;
  g_planeinfo.display = 0;
  g_planeinfo.xres_virtual = PANEL_HRES;
  g_planeinfo.yres_virtual = PANEL_VRES;

  d13x_lvds_init(PANEL_HRES, PANEL_VRES);

  /* 彩色条纹测试图案 */

  pixels_per_color = PANEL_HRES / 6;
  colors[0] = 0x0000FF; colors[1] = 0x00FF00; colors[2] = 0xFF0000;
  colors[3] = 0x00FFFF; colors[4] = 0xFF00FF; colors[5] = 0xFFFF00;

  for (i = 0; i < PANEL_HRES * PANEL_VRES; i++)
    {
      int x = i % PANEL_HRES;
      int idx = x / pixels_per_color;
      if (idx >= 6) idx = 5;
      g_framebuffer[i] = colors[idx];
    }

  g_fb_vtable.getvideoinfo = d13x_lvds_getvideoinfo;
  g_fb_vtable.getplaneinfo = d13x_lvds_getplaneinfo;
  g_fb_vtable.open = d13x_lvds_open;
  g_fb_vtable.close = d13x_lvds_close;

  g_fb_initialized = 1;
  return OK;
}

FAR struct fb_vtable_s *up_fbgetvplane(int display, int vplane)
{
  if (vplane == 0 && g_fb_initialized) return &g_fb_vtable;
  return NULL;
}

void up_fbuninitialize(int display) {}

