/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_i2c.c
 *
 * D13x I2C 驱动 (DesignWare IP, 来源: luban-lite hal_i2c.h)
 *
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/irq.h>
#include <nuttx/arch.h>
#include <nuttx/i2c/i2c_master.h>
#include <errno.h>
#include "chip.h"

/* DesignWare I2C 寄存器偏移 (来源: luban-lite hal_i2c.h) */

#define I2C_CTL               0x00
#define I2C_TAR               0x04
#define I2C_SAR               0x08
#define I2C_DATA_CMD          0x10
#define I2C_SS_SCL_HCNT       0x20
#define I2C_SS_SCL_LCNT       0x24
#define I2C_FS_SCL_HCNT       0x28
#define I2C_FS_SCL_LCNT       0x2C
#define I2C_INTR_MASK         0x38
#define I2C_INTR_CLR          0x3C
#define I2C_ENABLE            0x48
#define I2C_ENABLE_STATUS     0x4C
#define I2C_STATUS            0x50
#define I2C_TXFLR             0x98
#define I2C_RXFLR             0x9C

/* I2C_CTL 位定义 */

#define I2C_CTL_MASTER            (1 << 0)
#define I2C_CTL_SPEED_FS          (2 << 4)
#define I2C_CTL_RESTART_ENABLE    (1 << 6)

/* I2C_DATA_CMD 位定义 */

#define I2C_DATA_CMD_READ         (1 << 8)
#define I2C_DATA_CMD_STOP         (1 << 9)
#define I2C_DATA_CMD_RESTART      (1 << 10)

/* I2C_STATUS 位定义 */

#define I2C_STATUS_ACTIVITY       (1 << 0)
#define I2C_STATUS_TX_FULL        (1 << 1)
#define I2C_STATUS_TX_EMPTY       (2)
#define I2C_STATUS_RX_FULL        (4)
#define I2C_STATUS_RX_NOT_EMPTY   (8)

/* I2C_ENABLE */

#define I2C_ENABLE_BIT            (1 << 0)

/* I2C FIFO */

#define I2C_FIFO_DEPTH            8
#define I2C_TIMEOUT_VAL           1000

static struct i2c_master_s g_i2c0_dev;

static int d13x_i2c_wait_bus_idle(uint32_t base)
{
  int timeout = I2C_TIMEOUT_VAL;
  while (getreg32(base + I2C_STATUS) & I2C_STATUS_ACTIVITY)
    {
      if (--timeout <= 0) return -ETIMEDOUT;
    }
  return OK;
}

static int d13x_i2c_transfer(FAR struct i2c_master_s *dev,
                              FAR struct i2c_msg_s *msgs, int count)
{
  int i;
  uint32_t base = D13X_I2C0_BASE;

  for (i = 0; i < count; i++)
    {
      FAR struct i2c_msg_s *msg = &msgs[i];
      int j;
      int timeout;

      /* 设置目标地址 */

      putreg32(msg->addr, base + I2C_TAR);

      /* 写操作 */

      if (!(msg->flags & I2C_M_READ))
        {
          for (j = 0; j < msg->length; j++)
            {
              uint32_t cmd = msg->buffer[j];

              /* 最后一个字节且非 NOSTOP 时发送 STOP */

              if (j == msg->length - 1 && !(msg->flags & I2C_M_NOSTOP))
                {
                  cmd |= I2C_DATA_CMD_STOP;
                }

              /* 非第一个字节时发送 RESTART */

              if (j > 0)
                {
                  cmd |= I2C_DATA_CMD_RESTART;
                }

              putreg32(cmd, base + I2C_DATA_CMD);

              /* 等待 TX 空 */

              timeout = I2C_TIMEOUT_VAL;
              while (getreg32(base + I2C_TXFLR) == 0)
                {
                  if (--timeout <= 0) return -ETIMEDOUT;
                }
            }
        }
      else
        {
          /* 读操作: 发送 N 个读命令 */

          for (j = 0; j < msg->length; j++)
            {
              uint32_t cmd = I2C_DATA_CMD_READ;

              if (j == msg->length - 1 && !(msg->flags & I2C_M_NOSTOP))
                {
                  cmd |= I2C_DATA_CMD_STOP;
                }

              if (j > 0)
                {
                  cmd |= I2C_DATA_CMD_RESTART;
                }

              putreg32(cmd, base + I2C_DATA_CMD);

              /* 等待 RX 有数据 */

              timeout = I2C_TIMEOUT_VAL;
              while (getreg32(base + I2C_RXFLR) == 0)
                {
                  if (--timeout <= 0) return -ETIMEDOUT;
                }

              msg->buffer[j] = getreg32(base + I2C_DATA_CMD) & 0xFF;
            }
        }
    }

  return OK;
}

static int d13x_i2c_setup(FAR struct i2c_master_s *dev)
{
  uint32_t base = D13X_I2C0_BASE;
  uint32_t pclk = D13X_APB0_FREQ;  /* 100MHz */

  /* 禁用 I2C */

  putreg32(0, base + I2C_ENABLE);

  /* 等待禁用完成 */

  while (getreg32(base + I2C_ENABLE_STATUS) & 1);

  /* 配置为主机模式, Fast Mode (400KHz), 7-bit 地址 */

  putreg32(I2C_CTL_MASTER | I2C_CTL_SPEED_FS | I2C_CTL_RESTART_ENABLE,
           base + I2C_CTL);

  /* 配置 SCL 时序: Fast Mode 400KHz
   * HCNT = pclk / (freq * 3) - 8 = 100MHz / (400KHz * 3) - 8 ≈ 75
   * LCNT = pclk / (freq * 3) - 1 = 100MHz / (400KHz * 3) - 1 ≈ 82
   */

  uint32_t hcnt = pclk / (400000 * 3) - 8;
  uint32_t lcnt = pclk / (400000 * 3) - 1;

  putreg32(hcnt, base + I2C_FS_SCL_HCNT);
  putreg32(lcnt, base + I2C_FS_SCL_LCNT);

  /* 配置 FIFO 阈值 */

  putreg32(I2C_FIFO_DEPTH / 2 - 1, base + I2C_TX_TL);
  putreg32(I2C_FIFO_DEPTH / 2 - 1, base + I2C_RX_TL);

  /* 禁用所有中断 */

  putreg32(0, base + I2C_INTR_MASK);

  /* 使能 I2C */

  putreg32(I2C_ENABLE_BIT, base + I2C_ENABLE);

  /* 等待使能完成 */

  timeout = I2C_TIMEOUT_VAL;
  while (!(getreg32(base + I2C_ENABLE_STATUS) & 1))
    {
      if (--timeout <= 0) return -ETIMEDOUT;
    }

  return OK;
}

static int d13x_i2c_shutdown(FAR struct i2c_master_s *dev)
{
  uint32_t base = D13X_I2C0_BASE;
  putreg32(0, base + I2C_ENABLE);
  return OK;
}

static const struct i2c_ops_s g_d13x_i2c_ops =
{
  .transfer = d13x_i2c_transfer,
  .setup = d13x_i2c_setup,
  .shutdown = d13x_i2c_shutdown,
};

FAR struct i2c_master_s *d13x_i2c0_initialize(void)
{
  g_i2c0_dev.ops = &g_d13x_i2c_ops;
  d13x_i2c_setup(&g_i2c0_dev);
  return &g_i2c0_dev;
}

